CREATE TABLE articles (id BIGINT AUTO_INCREMENT, title VARCHAR(255), slug VARCHAR(255), content TEXT, date DATETIME, category_id BIGINT, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE cms (id BIGINT AUTO_INCREMENT, name VARCHAR(255) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, type VARCHAR(255) NOT NULL, active bool NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE categories (id BIGINT AUTO_INCREMENT, name VARCHAR(50) NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE quiz_users (id BIGINT UNSIGNED AUTO_INCREMENT, imie VARCHAR(50) NOT NULL, nazwisko VARCHAR(50) NOT NULL, email VARCHAR(70) NOT NULL, telefon VARCHAR(10) NOT NULL, uwagi TEXT, wiek BIGINT, created DATETIME, registered bool NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE role (id BIGINT AUTO_INCREMENT, name VARCHAR(50) NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE students (id BIGINT UNSIGNED AUTO_INCREMENT, imie VARCHAR(50) NOT NULL, nazwisko VARCHAR(50) NOT NULL, email VARCHAR(70) NOT NULL, telefon VARCHAR(10) NOT NULL, uwagi TEXT, created DATETIME, activated bool NOT NULL, registered bool NOT NULL, link VARCHAR(32) NOT NULL, PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
CREATE TABLE user (id BIGINT AUTO_INCREMENT, login VARCHAR(50) NOT NULL, password VARCHAR(64) NOT NULL, email VARCHAR(70) NOT NULL, role_id BIGINT, INDEX role_id_idx (role_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE utf8_unicode_ci ENGINE = INNODB;
ALTER TABLE user ADD CONSTRAINT user_role_id_role_id FOREIGN KEY (role_id) REFERENCES role(id);
